'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var format = require( '@stdlib/string/format' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var pkg = require( './../package.json' ).name;
var dgemmsw = require( './../lib/dgemmsw.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var options = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} N - number of rows and columns of each square matrix
* @returns {Function} benchmark function
*/
function createBenchmark( order, N ) {
	var A = uniform( N*N, -10.0, 10.0, options );
	var B = uniform( N*N, -10.0, 10.0, options );
	var C = uniform( N*N, -10.0, 10.0, options );
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dgemmsw( order, 'no-transpose', 'no-transpose', N, N, N, 1.0, A, N, B, N, 1.0, C, N );
			if ( isnan( z[ i%z.length ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* ## Notes
*
* -   The matrix dimensions (`16` to `512`) are chosen to span the default recursion cutoff, such that the benchmarks include both problems which are delegated to the conventional algorithm and problems which use one or more levels of the Strassen–Winograd recursion, for any cutoff from `16` to `256`.
*
* @private
*/
function main() {
	var len;
	var min;
	var max;
	var ord;
	var f;
	var i;
	var j;

	min = 4; // 2^min
	max = 9; // 2^max

	for ( i = 0; i < LAYOUTS.length; i++ ) {
		ord = LAYOUTS[ i ];
		for ( j = min; j <= max; j++ ) {
			len = pow( 2, j );
			f = createBenchmark( ord, len );
			bench( format( '%s:order=%s,trans(A)=false,trans(B)=false,size=%d', pkg, ord, len*len ), f );
		}
	}
}

main();
